package com.example.gidroreport\n\nimport android.content.ContentValues\nimport android.content.Intent\nimport android.graphics.Bitmap\nimport android.graphics.BitmapFactory\nimport android.graphics.Canvas\nimport android.graphics.Color\nimport android.graphics.Paint\nimport android.graphics.pdf.PdfDocument\nimport android.net.Uri\nimport android.os.Bundle\nimport android.provider.MediaStore\nimport android.text.Layout\nimport android.text.StaticLayout\nimport android.text.TextPaint\nimport androidx.activity.compose.setContent\nimport androidx.activity.result.PickVisualMediaRequest\nimport androidx.activity.result.contract.ActivityResultContracts\nimport androidx.appcompat.app.AppCompatActivity\nimport androidx.appcompat.app.AppCompatDelegate\nimport androidx.compose.foundation.layout.Arrangement\nimport androidx.compose.foundation.layout.Column\nimport androidx.compose.foundation.layout.PaddingValues\nimport androidx.compose.foundation.layout.Row\nimport androidx.compose.foundation.layout.fillMaxSize\nimport androidx.compose.foundation.layout.fillMaxWidth\nimport androidx.compose.foundation.layout.padding\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.items\nimport androidx.compose.material3.AlertDialog\nimport androidx.compose.material3.Button\nimport androidx.compose.material3.Card\nimport androidx.compose.material3.ExperimentalMaterial3Api\nimport androidx.compose.material3.FilterChip\nimport androidx.compose.material3.MaterialTheme\nimport androidx.compose.material3.OutlinedButton\nimport androidx.compose.material3.OutlinedTextField\nimport androidx.compose.material3.Scaffold\nimport androidx.compose.material3.Text\nimport androidx.compose.material3.TextButton\nimport androidx.compose.material3.TopAppBar\nimport androidx.compose.runtime.Composable\nimport androidx.compose.runtime.MutableState\nimport androidx.compose.runtime.getValue\nimport androidx.compose.runtime.mutableStateListOf\nimport androidx.compose.runtime.mutableStateOf\nimport androidx.compose.runtime.remember\nimport androidx.compose.runtime.rememberCoroutineScope\nimport androidx.compose.runtime.setValue\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.res.stringResource\nimport androidx.compose.ui.unit.dp\nimport androidx.compose.ui.unit.sp\nimport androidx.core.os.LocaleListCompat\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.launch\nimport kotlinx.coroutines.withContext\nimport java.text.SimpleDateFormat\nimport java.util.Date\nimport java.util.Locale\n\nclass MainActivity : AppCompatActivity() {\n\n    data class PhotoItem(val uri: Uri, val comment: MutableState<String>)\n    data class CustomField(val name: MutableState<String>, val value: MutableState<String>)\n\n    private val photos = mutableStateListOf<PhotoItem>()\n    private val customFields = mutableStateListOf<CustomField>()\n    private var logoUri: Uri? = null\n    private var pendingCameraUri: Uri? = null\n\n    private val takePicture = registerForActivityResult(ActivityResultContracts.TakePicture()) { success ->\n        if (success) {\n            pendingCameraUri?.let { photos.add(PhotoItem(it, mutableStateOf(""))) }\n        }\n        pendingCameraUri = null\n    }\n\n    private val pickMedia = registerForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->\n        if (uri != null) photos.add(PhotoItem(uri, mutableStateOf("")))\n    }\n\n    private val pickLogo = registerForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->\n        if (uri != null) logoUri = uri\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        val saved = getSharedPreferences("settings", MODE_PRIVATE).getString("language", "")\n        if (!saved.isNullOrBlank()) {\n            AppCompatDelegate.setApplicationLocales(LocaleListCompat.forLanguageTags(saved))\n        }\n        super.onCreate(savedInstanceState)\n        setContent { MaterialTheme { ReportScreen() } }\n    }\n\n    private fun applyLanguage(tag: String) {\n        getSharedPreferences("settings", MODE_PRIVATE).edit().putString("language", tag).apply()\n        AppCompatDelegate.setApplicationLocales(LocaleListCompat.forLanguageTags(tag))\n    }\n\n    private fun launchCamera() {\n        val values = ContentValues().apply {\n            put(MediaStore.Images.Media.DISPLAY_NAME, "GidroReport_${System.currentTimeMillis()}.jpg")\n            put(MediaStore.Images.Media.MIME_TYPE, "image/jpeg")\n        }\n        val uri = contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values)\n        if (uri != null) {\n            pendingCameraUri = uri\n            takePicture.launch(uri)\n        }\n    }\n\n    @OptIn(ExperimentalMaterial3Api::class)\n    @Composable\n    fun ReportScreen() {\n        var installerName by remember { mutableStateOf("") }\n        var installerCertificate by remember { mutableStateOf("") }\n        var installerContact by remember { mutableStateOf("") }\n        var siteAddress by remember { mutableStateOf("") }\n        var clientRepresentative by remember { mutableStateOf("") }\n        var workPeriod by remember { mutableStateOf("") }\n        var substrateMaterial by remember { mutableStateOf("") }\n        var instructionsRead by remember { mutableStateOf("") }\n        var levelingCompound by remember { mutableStateOf("") }\n        var primer by remember { mutableStateOf("") }\n        var waterproofingMaterial by remember { mutableStateOf("") }\n        var drainType by remember { mutableStateOf("") }\n        var reinforcementTapes by remember { mutableStateOf("") }\n        var penetrationSealants by remember { mutableStateOf("") }\n        var adhesiveMortar by remember { mutableStateOf("") }\n        var tiles by remember { mutableStateOf("") }\n        var grout by remember { mutableStateOf("") }\n        var elasticJoints by remember { mutableStateOf("") }\n        var underfloorHeating by remember { mutableStateOf("") }\n        var thresholdRise by remember { mutableStateOf("") }\n        var floorSlope by remember { mutableStateOf("") }\n        var wallArea by remember { mutableStateOf("") }\n        var floorArea by remember { mutableStateOf("") }\n        var wallConsumption by remember { mutableStateOf("") }\n        var floorConsumption by remember { mutableStateOf("") }\n        var wallThicknessRequirement by remember { mutableStateOf("") }\n        var wallThicknessActual by remember { mutableStateOf("") }\n        var wallThicknessResult by remember { mutableStateOf("") }\n        var floorThicknessRequirement by remember { mutableStateOf("") }\n        var floorThicknessActual by remember { mutableStateOf("") }\n        var floorThicknessResult by remember { mutableStateOf("") }\n        var result by remember { mutableStateOf("") }\n        var supervisorName by remember { mutableStateOf("") }\n        var supervisorCertificate by remember { mutableStateOf("") }\n        var supervisorContact by remember { mutableStateOf("") }\n        var reportDate by remember { mutableStateOf("") }\n        var statusMessage by remember { mutableStateOf("") }\n        var showFieldDialog by remember { mutableStateOf(false) }\n        var newFieldName by remember { mutableStateOf("") }\n        var newFieldValue by remember { mutableStateOf("") }\n\n        val scope = rememberCoroutineScope()\n        val dateFormat = SimpleDateFormat("dd.MM.yyyy", Locale.getDefault())\n\n        if (showFieldDialog) {\n            AlertDialog(\n                onDismissRequest = { showFieldDialog = false },\n                title = { Text(stringResource(R.string.add_custom_field)) },\n                text = {\n                    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {\n                        OutlinedTextField(\n                            value = newFieldName,\n                            onValueChange = { newFieldName = it },\n                            label = { Text(stringResource(R.string.custom_field_name)) },\n                            modifier = Modifier.fillMaxWidth()\n                        )\n                        OutlinedTextField(\n                            value = newFieldValue,\n                            onValueChange = { newFieldValue = it },\n                            label = { Text(stringResource(R.string.custom_field_value)) },\n                            modifier = Modifier.fillMaxWidth()\n                        )\n                    }\n                },\n                confirmButton = {\n                    TextButton(onClick = {\n                        if (newFieldName.isNotBlank()) {\n                            customFields.add(\n                                CustomField(mutableStateOf(newFieldName), mutableStateOf(newFieldValue))\n                            )\n                        }\n                        newFieldName = ""\n                        newFieldValue = ""\n                        showFieldDialog = false\n                    }) { Text(stringResource(R.string.add)) }\n                },\n                dismissButton = {\n                    TextButton(onClick = { showFieldDialog = false }) {\n                        Text(stringResource(R.string.cancel))\n                    }\n                }\n            )\n        }\n\n        Scaffold(topBar = { TopAppBar(title = { Text(stringResource(R.string.app_name)) }) }) { padding ->\n            LazyColumn(\n                modifier = Modifier.padding(padding).fillMaxSize(),\n                contentPadding = PaddingValues(16.dp),\n                verticalArrangement = Arrangement.spacedBy(12.dp)\n            ) {\n                item {\n                    Text(stringResource(R.string.language), fontSize = 18.sp)\n                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                        FilterChip(selected = false, onClick = { applyLanguage("fi") }, label = { Text("Suomi") })\n                        FilterChip(selected = false, onClick = { applyLanguage("ru") }, label = { Text("Русский") })\n                        FilterChip(selected = false, onClick = { applyLanguage("en") }, label = { Text("English") })\n                    }\n                }\n\n                item {\n                    OutlinedButton(\n                        onClick = {\n                            pickLogo.launch(\n                                PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly)\n                            )\n                        },\n                        modifier = Modifier.fillMaxWidth()\n                    ) { Text(stringResource(R.string.choose_logo)) }\n                    if (logoUri != null) Text(stringResource(R.string.logo_selected))\n                }\n\n                item { Text(stringResource(R.string.section_installer), fontSize = 18.sp) }\n                item {\n                    OutlinedTextField(value = installerName, onValueChange = { installerName = it }, label = { Text(stringResource(R.string.installer_name)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = installerCertificate, onValueChange = { installerCertificate = it }, label = { Text(stringResource(R.string.installer_certificate)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = installerContact, onValueChange = { installerContact = it }, label = { Text(stringResource(R.string.installer_contact)) }, modifier = Modifier.fillMaxWidth())\n                }\n\n                item { Text(stringResource(R.string.section_site), fontSize = 18.sp) }\n                item {\n                    OutlinedTextField(value = siteAddress, onValueChange = { siteAddress = it }, label = { Text(stringResource(R.string.site_address)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = clientRepresentative, onValueChange = { clientRepresentative = it }, label = { Text(stringResource(R.string.client_representative)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = workPeriod, onValueChange = { workPeriod = it }, label = { Text(stringResource(R.string.work_period)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = substrateMaterial, onValueChange = { substrateMaterial = it }, label = { Text(stringResource(R.string.substrate_material)) }, modifier = Modifier.fillMaxWidth())\n                    Text(stringResource(R.string.instructions_read))\n                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                        FilterChip(selected = instructionsRead == stringResource(R.string.yes), onClick = { instructionsRead = stringResource(R.string.yes) }, label = { Text(stringResource(R.string.yes)) })\n                        FilterChip(selected = instructionsRead == stringResource(R.string.no), onClick = { instructionsRead = stringResource(R.string.no) }, label = { Text(stringResource(R.string.no)) })\n                    }\n                }\n\n                item { Text(stringResource(R.string.section_system), fontSize = 18.sp) }\n                item {\n                    OutlinedTextField(value = levelingCompound, onValueChange = { levelingCompound = it }, label = { Text(stringResource(R.string.leveling_compound)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = primer, onValueChange = { primer = it }, label = { Text(stringResource(R.string.primer)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = waterproofingMaterial, onValueChange = { waterproofingMaterial = it }, label = { Text(stringResource(R.string.waterproofing_material)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = drainType, onValueChange = { drainType = it }, label = { Text(stringResource(R.string.drain_type_flange)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = reinforcementTapes, onValueChange = { reinforcementTapes = it }, label = { Text(stringResource(R.string.reinforcement_tapes)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = penetrationSealants, onValueChange = { penetrationSealants = it }, label = { Text(stringResource(R.string.penetration_sealants)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = adhesiveMortar, onValueChange = { adhesiveMortar = it }, label = { Text(stringResource(R.string.adhesive_mortar)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = tiles, onValueChange = { tiles = it }, label = { Text(stringResource(R.string.tiles)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = grout, onValueChange = { grout = it }, label = { Text(stringResource(R.string.grout)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = elasticJoints, onValueChange = { elasticJoints = it }, label = { Text(stringResource(R.string.elastic_joints)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = underfloorHeating, onValueChange = { underfloorHeating = it }, label = { Text(stringResource(R.string.underfloor_heating)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = thresholdRise, onValueChange = { thresholdRise = it }, label = { Text(stringResource(R.string.threshold_drain_rise)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = floorSlope, onValueChange = { floorSlope = it }, label = { Text(stringResource(R.string.floor_slope)) }, modifier = Modifier.fillMaxWidth())\n                }\n\n                item { Text(stringResource(R.string.section_quantities), fontSize = 18.sp) }\n                item {\n                    OutlinedTextField(value = wallArea, onValueChange = { wallArea = it }, label = { Text(stringResource(R.string.wall_area)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = floorArea, onValueChange = { floorArea = it }, label = { Text(stringResource(R.string.floor_area)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = wallConsumption, onValueChange = { wallConsumption = it }, label = { Text(stringResource(R.string.wall_consumption)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = floorConsumption, onValueChange = { floorConsumption = it }, label = { Text(stringResource(R.string.floor_consumption)) }, modifier = Modifier.fillMaxWidth())\n                }\n\n                item { Text(stringResource(R.string.section_checks), fontSize = 18.sp) }\n                item {\n                    OutlinedTextField(value = wallThicknessRequirement, onValueChange = { wallThicknessRequirement = it }, label = { Text(stringResource(R.string.wall_thickness_requirement)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = wallThicknessActual, onValueChange = { wallThicknessActual = it }, label = { Text(stringResource(R.string.wall_thickness_actual)) }, modifier = Modifier.fillMaxWidth())\n                    Text(stringResource(R.string.wall_thickness_result))\n                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                        FilterChip(selected = wallThicknessResult == stringResource(R.string.meets_requirements), onClick = { wallThicknessResult = stringResource(R.string.meets_requirements) }, label = { Text(stringResource(R.string.meets_requirements)) })\n                        FilterChip(selected = wallThicknessResult == stringResource(R.string.does_not_meet_requirements), onClick = { wallThicknessResult = stringResource(R.string.does_not_meet_requirements) }, label = { Text(stringResource(R.string.does_not_meet_requirements)) })\n                    }\n                    OutlinedTextField(value = floorThicknessRequirement, onValueChange = { floorThicknessRequirement = it }, label = { Text(stringResource(R.string.floor_thickness_requirement)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = floorThicknessActual, onValueChange = { floorThicknessActual = it }, label = { Text(stringResource(R.string.floor_thickness_actual)) }, modifier = Modifier.fillMaxWidth())\n                    Text(stringResource(R.string.floor_thickness_result))\n                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                        FilterChip(selected = floorThicknessResult == stringResource(R.string.meets_requirements), onClick = { floorThicknessResult = stringResource(R.string.meets_requirements) }, label = { Text(stringResource(R.string.meets_requirements)) })\n                        FilterChip(selected = floorThicknessResult == stringResource(R.string.does_not_meet_requirements), onClick = { floorThicknessResult = stringResource(R.string.does_not_meet_requirements) }, label = { Text(stringResource(R.string.does_not_meet_requirements)) })\n                    }\n                }\n\n                item { Text(stringResource(R.string.inspection_result), fontSize = 18.sp) }\n                item {\n                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                        FilterChip(selected = result == stringResource(R.string.result_approved), onClick = { result = stringResource(R.string.result_approved) }, label = { Text(stringResource(R.string.result_approved)) })\n                        FilterChip(selected = result == stringResource(R.string.result_rejected), onClick = { result = stringResource(R.string.result_rejected) }, label = { Text(stringResource(R.string.result_rejected)) })\n                    }\n                }\n\n                item { Text(stringResource(R.string.section_supervisor), fontSize = 18.sp) }\n                item {\n                    OutlinedTextField(value = supervisorName, onValueChange = { supervisorName = it }, label = { Text(stringResource(R.string.supervisor_name)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = supervisorCertificate, onValueChange = { supervisorCertificate = it }, label = { Text(stringResource(R.string.supervisor_certificate)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = supervisorContact, onValueChange = { supervisorContact = it }, label = { Text(stringResource(R.string.supervisor_contact)) }, modifier = Modifier.fillMaxWidth())\n                    OutlinedTextField(value = reportDate, onValueChange = { reportDate = it }, label = { Text(stringResource(R.string.report_date)) }, modifier = Modifier.fillMaxWidth())\n                }\n\n                item { Text(stringResource(R.string.custom_fields), fontSize = 18.sp) }\n                items(customFields) { field ->\n                    Card {\n                        Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {\n                            Text(field.name.value)\n                            Text(field.value.value)\n                            OutlinedButton(onClick = { customFields.remove(field) }, modifier = Modifier.fillMaxWidth()) {\n                                Text(stringResource(R.string.delete))\n                            }\n                        }\n                    }\n                }\n                item {\n                    Button(onClick = { showFieldDialog = true }, modifier = Modifier.fillMaxWidth()) {\n                        Text(stringResource(R.string.add_custom_field))\n                    }\n                }\n\n                item {\n                    Button(onClick = { launchCamera() }, modifier = Modifier.fillMaxWidth()) {\n                        Text(stringResource(R.string.take_photo))\n                    }\n                }\n                item {\n                    Button(\n                        onClick = {\n                            pickMedia.launch(PickVisualMediaRequest(ActivityResultContracts.PickVisualMedia.ImageOnly))\n                        },\n                        modifier = Modifier.fillMaxWidth()\n                    ) { Text(stringResource(R.string.choose_photo)) }\n                }\n\n                items(photos) { photo ->\n                    Card {\n                        Column(modifier = Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {\n                            PhotoImage(photo.uri)\n                            OutlinedTextField(\n                                value = photo.comment.value,\n                                onValueChange = { photo.comment.value = it },\n                                label = { Text(stringResource(R.string.photo_comment)) },\n                                modifier = Modifier.fillMaxWidth()\n                            )\n                        }\n                    }\n                }\n\n                item {\n                    Button(\n                        onClick = {\n                            scope.launch {\n                                statusMessage = getString(R.string.creating_pdf)\n                                val uri = createPdf(\n                                    installerName, installerCertificate, installerContact,\n                                    siteAddress, clientRepresentative, workPeriod,\n                                    substrateMaterial, instructionsRead,\n                                    levelingCompound, primer, waterproofingMaterial, drainType,\n                                    reinforcementTapes, penetrationSealants, adhesiveMortar,\n                                    tiles, grout, elasticJoints, underfloorHeating,\n                                    thresholdRise, floorSlope,\n                                    wallArea, floorArea, wallConsumption, floorConsumption,\n                                    wallThicknessRequirement, wallThicknessActual, wallThicknessResult,\n                                    floorThicknessRequirement, floorThicknessActual, floorThicknessResult,\n                                    result, supervisorName, supervisorCertificate, supervisorContact,\n                                    reportDate.ifBlank { dateFormat.format(Date()) }\n                                )\n                                statusMessage = if (uri != null) {\n                                    sharePdf(uri)\n                                    getString(R.string.pdf_created)\n                                } else getString(R.string.pdf_failed)\n                            }\n                        },\n                        modifier = Modifier.fillMaxWidth()\n                    ) { Text(stringResource(R.string.create_pdf)) }\n                    if (statusMessage.isNotEmpty()) Text(statusMessage)\n                }\n            }\n        }\n    }\n\n    @Composable\n    fun PhotoImage(uri: Uri) {\n        val bitmap = remember(uri) { loadBitmap(uri, 900) }\n        bitmap?.let {\n            androidx.compose.foundation.Image(\n                bitmap = it.asImageBitmap(),\n                contentDescription = stringResource(R.string.pdf_photo),\n                modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),\n                contentScale = androidx.compose.ui.layout.ContentScale.Crop\n            )\n        }\n    }\n\n    private fun loadBitmap(uri: Uri, maxSize: Int): Bitmap? {\n        return try {\n            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }\n            contentResolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, bounds) }\n            var sample = 1\n            while (bounds.outWidth / sample > maxSize || bounds.outHeight / sample > maxSize) sample *= 2\n            val options = BitmapFactory.Options().apply { inSampleSize = sample }\n            contentResolver.openInputStream(uri)?.use { BitmapFactory.decodeStream(it, null, options) }\n        } catch (e: Exception) { null }\n    }\n\n    private suspend fun createPdf(\n        installerName: String, installerCertificate: String, installerContact: String,\n        siteAddress: String, clientRepresentative: String, workPeriod: String,\n        substrateMaterial: String, instructionsRead: String,\n        levelingCompound: String, primer: String, waterproofingMaterial: String, drainType: String,\n        reinforcementTapes: String, penetrationSealants: String, adhesiveMortar: String,\n        tiles: String, grout: String, elasticJoints: String, underfloorHeating: String,\n        thresholdRise: String, floorSlope: String,\n        wallArea: String, floorArea: String, wallConsumption: String, floorConsumption: String,\n        wallThicknessRequirement: String, wallThicknessActual: String, wallThicknessResult: String,\n        floorThicknessRequirement: String, floorThicknessActual: String, floorThicknessResult: String,\n        result: String, supervisorName: String, supervisorCertificate: String,\n        supervisorContact: String, reportDate: String\n    ): Uri? = withContext(Dispatchers.IO) {\n        try {\n            val document = PdfDocument()\n            val pageWidth = 595\n            val pageHeight = 842\n            var pageNumber = 1\n            var page = document.startPage(PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNumber).create())\n            var canvas = page.canvas\n            var y = 50f\n\n            val title = Paint().apply { color = Color.BLACK; textSize = 16f; isFakeBoldText = true }\n            val header = Paint().apply { color = Color.BLACK; textSize = 12f; isFakeBoldText = true }\n            val small = Paint().apply { color = Color.DKGRAY; textSize = 9f }\n            val body = Paint().apply { color = Color.BLACK; textSize = 9f }\n            val textPaint = TextPaint().apply { color = Color.BLACK; textSize = 10f }\n\n            fun nextPage() {\n                document.finishPage(page)\n                pageNumber++\n                page = document.startPage(PdfDocument.PageInfo.Builder(pageWidth, pageHeight, pageNumber).create())\n                canvas = page.canvas\n                y = 50f\n            }\n\n            fun addText(label: String, value: String) {\n                val text = "$label: ${value.ifBlank { \"—\" }}"\n                val layout = StaticLayout.Builder.obtain(text, 0, text.length, textPaint, pageWidth - 100)\n                    .setAlignment(Layout.Alignment.ALIGN_NORMAL).setLineSpacing(1f, 1f).build()\n                if (y + layout.height > pageHeight - 60) nextPage()\n                canvas.drawText(label, 50f, y, small)\n                y += 12f\n                canvas.save(); canvas.translate(50f, y); layout.draw(canvas); canvas.restore()\n                y += layout.height + 6f\n            }\n\n            fun section(titleText: String) {\n                if (y > pageHeight - 100) nextPage()\n                y += 10f\n                canvas.drawText(titleText, 50f, y, header)\n                y += 18f\n            }\n\n            logoUri?.let { uri ->\n                loadBitmap(uri, 400)?.let { logo ->\n                    val scale = minOf(120f / logo.width, 60f / logo.height)\n                    val w = logo.width * scale\n                    val h = logo.height * scale\n                    canvas.drawBitmap(\n                        Bitmap.createScaledBitmap(logo, w.toInt().coerceAtLeast(1), h.toInt().coerceAtLeast(1), true),\n                        pageWidth - 50f - w, 35f, null\n                    )\n                }\n            }\n\n            canvas.drawText(getString(R.string.pdf_title), 50f, y, title)\n            y += 28f\n\n            section(getString(R.string.pdf_installer_section))\n            addText(getString(R.string.installer_name), installerName)\n            addText(getString(R.string.installer_certificate), installerCertificate)\n            addText(getString(R.string.installer_contact), installerContact)\n\n            section(getString(R.string.pdf_site_section))\n            addText(getString(R.string.site_address), siteAddress)\n            addText(getString(R.string.client_representative), clientRepresentative)\n            addText(getString(R.string.work_period), workPeriod)\n            addText(getString(R.string.substrate_material), substrateMaterial)\n            addText(getString(R.string.instructions_read), instructionsRead)\n\n            section(getString(R.string.pdf_system_section))\n            addText(getString(R.string.leveling_compound), levelingCompound)\n            addText(getString(R.string.primer), primer)\n            addText(getString(R.string.waterproofing_material), waterproofingMaterial)\n            addText(getString(R.string.drain_type_flange), drainType)\n            addText(getString(R.string.reinforcement_tapes), reinforcementTapes)\n            addText(getString(R.string.penetration_sealants), penetrationSealants)\n            addText(getString(R.string.adhesive_mortar), adhesiveMortar)\n            addText(getString(R.string.tiles), tiles)\n            addText(getString(R.string.grout), grout)\n            addText(getString(R.string.elastic_joints), elasticJoints)\n            addText(getString(R.string.underfloor_heating), underfloorHeating)\n            addText(getString(R.string.threshold_drain_rise), thresholdRise)\n            addText(getString(R.string.floor_slope), floorSlope)\n\n            section(getString(R.string.pdf_quantities_section))\n            addText(getString(R.string.wall_area), wallArea)\n            addText(getString(R.string.floor_area), floorArea)\n            addText(getString(R.string.wall_consumption), wallConsumption)\n            addText(getString(R.string.floor_consumption), floorConsumption)\n\n            section(getString(R.string.pdf_checks_section))\n            addText(getString(R.string.wall_thickness_requirement), wallThicknessRequirement)\n            addText(getString(R.string.wall_thickness_actual), wallThicknessActual)\n            addText(getString(R.string.wall_thickness_result), wallThicknessResult)\n            addText(getString(R.string.floor_thickness_requirement), floorThicknessRequirement)\n            addText(getString(R.string.floor_thickness_actual), floorThicknessActual)\n            addText(getString(R.string.floor_thickness_result), floorThicknessResult)\n\n            if (customFields.isNotEmpty()) {\n                section(getString(R.string.pdf_custom_fields))\n                customFields.forEach { addText(it.name.value, it.value.value) }\n            }\n\n            section(getString(R.string.pdf_result_section))\n            canvas.drawText(\n                "${getString(R.string.pdf_result_label)} - ${result.ifBlank { \"—\" }}",\n                50f, y, title\n            )\n            y += 25f\n\n            section(getString(R.string.pdf_supervisor_section))\n            addText(getString(R.string.supervisor_name), supervisorName)\n            addText(getString(R.string.supervisor_certificate), supervisorCertificate)\n            addText(getString(R.string.supervisor_contact), supervisorContact)\n            addText(getString(R.string.report_date), reportDate)\n\n            photos.chunked(4).forEach { chunk ->\n                nextPage()\n                canvas.drawText(getString(R.string.pdf_photos), 50f, y, header)\n                y += 22f\n                val margin = 50f\n                val gap = 15f\n                val cellWidth = (pageWidth - margin * 2 - gap) / 2f\n                val cellHeight = 220f\n                val rowHeight = cellHeight + 45f\n                chunk.forEachIndexed { i, photo ->\n                    val col = i % 2\n                    val row = i / 2\n                    val x = margin + col * (cellWidth + gap)\n                    val top = y + row * rowHeight\n                    canvas.drawText("${getString(R.string.pdf_photo)} ${photos.indexOf(photo) + 1}", x, top, small)\n                    loadBitmap(photo.uri, 1200)?.let { bmp ->\n                        val scale = minOf(cellWidth / bmp.width, cellHeight / bmp.height)\n                        val w = bmp.width * scale\n                        val h = bmp.height * scale\n                        canvas.drawBitmap(\n                            Bitmap.createScaledBitmap(bmp, w.toInt().coerceAtLeast(1), h.toInt().coerceAtLeast(1), true),\n                            x + (cellWidth - w) / 2f, top + 12f + (cellHeight - h) / 2f, null\n                        )\n                    }\n                    canvas.drawText(photo.comment.value.ifBlank { \"—\" }.take(80), x, top + cellHeight + 22f, body)\n                }\n            }\n\n            document.finishPage(page)\n\n            val fileName = "Valvontapoytakirja_${SimpleDateFormat(\"yyyyMMdd_HHmmss\", Locale.getDefault()).format(Date())}.pdf"\n            val values = ContentValues().apply {\n                put(MediaStore.Downloads.DISPLAY_NAME, fileName)\n                put(MediaStore.Downloads.MIME_TYPE, "application/pdf")\n            }\n            val uri = contentResolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values)\n                ?: return@withContext null\n            contentResolver.openOutputStream(uri)?.use { document.writeTo(it) }\n            document.close()\n            uri\n        } catch (e: Exception) { null }\n    }\n\n    private fun sharePdf(uri: Uri) {\n        val intent = Intent(Intent.ACTION_SEND).apply {\n            type = "application/pdf"\n            putExtra(Intent.EXTRA_STREAM, uri)\n            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)\n        }\n        startActivity(Intent.createChooser(intent, getString(R.string.share_pdf)))\n    }\n}
